<?php use SwimlogStandalone\CalendarView as CV; use SwimlogStandalone\WorkoutDetails as WD; use SwimLogEvaluation\Workout; ?>
<article class="workout-content" data-workout-id="<?php echo esc_attr($detail['id']); ?>">
<h3><?php echo esc_html($detail['label'].' · Workout #'.$detail['id']); ?></h3>
<dl class="workout-metrics"><?php foreach($detail['summary'] as $label=>$value): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($value); ?></dd></div><?php endforeach; ?></dl>
<?php if($detail['type']!=='pool'): ?><section class="workout-route"><h3>Recorded route</h3><?php if($detail['route']): echo $detail['route']; ?><p class="detail-caption">Recorded GPS only. Gaps remain disconnected; no external map service receives your route.</p><?php else: ?><p>No usable GPS route is recorded for this activity.</p><?php endif; ?></section><?php endif; ?>
<?php if($detail['type']==='open_water'): $analytics=$detail['analytics']; ?><section><h3>Open-water summary</h3><dl class="workout-metrics"><div><dt>Elapsed pace / 100 m</dt><dd><?php echo esc_html(Workout::format_duration($analytics['elapsed_pace_100m_ms']??null)); ?></dd></div><div><dt>Moving pace / 100 m</dt><dd><?php echo esc_html(Workout::format_duration($analytics['moving_pace_100m_ms']??null)); ?></dd></div></dl><p class="detail-caption">Paces are derived by the Swim Log service from stored distance and duration.</p>
<?php if(!empty($analytics['splits'])): ?><div class="detail-table-wrap" role="region" aria-label="Open-water splits" tabindex="0"><table><thead><tr><th>Distance</th><th>Elapsed split</th><th>Cumulative time</th><th>Estimated moving split</th></tr></thead><tbody><?php foreach($analytics['splits'] as $split): ?><tr><td><?php echo esc_html(CV::distance($split['distance_m'])); ?></td><td><?php echo esc_html(Workout::format_duration($split['split_time_ms'])); ?></td><td><?php echo esc_html(Workout::format_duration($split['cumulative_time_ms'])); ?></td><td><?php echo esc_html(Workout::format_duration($split['moving_split_time_ms']??null)); ?></td></tr><?php endforeach; ?></tbody></table></div><p class="detail-caption">Split boundaries use interpolation. Moving splits are estimates when available.</p><?php endif; ?></section><?php endif; ?>
<section><h3>Laps</h3><?php if(!$detail['laps']): ?><p>No lap records are available.</p><?php else: ?><div class="detail-table-wrap" role="region" aria-label="Workout laps" tabindex="0"><table><thead><tr><th scope="col">Lap</th><th scope="col">Distance (m)</th><th scope="col">Elapsed</th><th scope="col">Recorded moving time</th><?php if($detail['type']==='pool'): ?><th scope="col">Stroke</th><?php endif; ?></tr></thead><tbody><?php foreach($detail['laps'] as $lap): ?><tr><td><?php echo esc_html($lap->sequence_no); ?></td><td><?php echo esc_html(CV::distance($lap->distance_m)); ?></td><td><?php echo esc_html(Workout::format_duration($lap->elapsed_time_ms)); ?></td><td><?php echo esc_html(Workout::format_duration($lap->moving_time_ms)); ?></td><?php if($detail['type']==='pool'): ?><td><?php echo esc_html(WD::stroke($lap->stroke)); ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if($detail['type']==='pool'): ?><section><h3>Lengths and rest</h3><?php if(!$detail['lengths']): ?><p>No length records are available.</p><?php else: ?><div class="detail-table-wrap" role="region" aria-label="Pool lengths and rest" tabindex="0"><table><thead><tr><th scope="col">Length</th><th scope="col">Type</th><th scope="col">Distance (m)</th><th scope="col">Stroke</th><th scope="col">Stroke count</th><th scope="col">Elapsed</th><th scope="col">SWOLF</th></tr></thead><tbody><?php foreach($detail['lengths'] as $length): $isRest=WD::isRestLength($length); ?><tr><td><?php echo esc_html($length->sequence_no); ?></td><td><?php echo esc_html($isRest?'Rest':$length->length_type); ?></td><td><?php echo esc_html(CV::distance($length->distance_m)); ?></td><td><?php echo esc_html($isRest?'—':WD::stroke($length->stroke)); ?></td><td><?php echo esc_html($isRest?'—':($length->stroke_count??'—')); ?></td><td><?php echo esc_html(Workout::format_duration($length->elapsed_time_ms)); ?></td><td><?php echo esc_html($isRest?'—':($length->swolf_score??'—')); ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if($detail['performances']): ?><section><h3>Recorded performances</h3><div class="detail-table-wrap" role="region" aria-label="Recorded swim performances" tabindex="0"><table><thead><tr><th>Distance</th><th>Stroke</th><th>Time</th><th>Personal best</th></tr></thead><tbody><?php foreach($detail['performances'] as $performance): ?><tr><td><?php echo esc_html(CV::distance($performance->distance_value,$performance->course_unit)); ?></td><td><?php echo esc_html(WD::stroke($performance->stroke)); ?></td><td><?php echo esc_html(Workout::format_duration($performance->duration_ms)); ?></td><td><?php echo !empty($performance->is_personal_best)?'★ Personal best':'—'; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; endif; ?>
</article>
